def java_hash(s):
    h=0
    for c in s:
        h = (31*h + ord(c)) & 0xFFFFFFFF
        # convert to signed?
    # java int is signed 32, but for hashing need signed? Actually HashMap uses (h = key.hashCode()) ^ (h>>>16)
    # Convert to signed 32
    if h >= 0x80000000:
        h -= 0x100000000
    return h

def bucket(s, cap=16):
    h = java_hash(s)
    # unsigned shift?
    # In Java, h is int, h>>>16 is logical shift
    uh = h & 0xFFFFFFFF
    spread = (h ^ (uh >> 16)) & 0xFFFFFFFF
    # convert spread to signed? Actually & (n-1) uses int bits
    return spread & (cap-1)

for s in ["a","b","c","d", "aaa","zzz","myid","ditaa_diagram_1","ditaa_diagram_2","id1","id2","id3"]:
    print(s, java_hash(s), bucket(s))
PY"}

